immediate-ceiling-priority-protocol.pseudocode:
class CeilingMutex:
    def __init__(self, ceiling):
        self.ceiling = ceiling  # 사용 태스크 중 최고 우선순위
        self.saved = []  # 잠금 시점의 원래 우선순위

    def lock(self, task):
        # 단일 CPU: 보유자는 상한으로 실행되므로
        # 내가 실행 중이면 자원은 항상 비어 있음
        self.saved.append(task.priority)
        task.priority = max(task.priority, self.ceiling)

    def unlock(self, task):
        task.priority = self.saved.pop()  # 원래 값 복귀
        schedule()  # 대기하던 태스크에 실행 기회
